export const countyBySlug = (slug: string): MaCountyRef | undefined =>
  MA_COUNTIES.find((c) => c.slug === slug);
export const countyRef = (name: MaCounty): MaCountyRef =>
  MA_COUNTIES.find((c) => c.name === name)!;
export const townBySlug = (slug: string): MaTown | undefined =>
  MA_TOWNS.find((t) => t.slug === slug);
export const townsInCounty = (county: MaCounty): MaTown[] =>
  MA_TOWNS.filter((t) => t.county === county);

const toRad = (d: number) => (d * Math.PI) / 180;
/** Great-circle distance in statute miles. */
export const milesBetween = (
  a: { lat: number; lng: number },
  b: { lat: number; lng: number },
): number => {
  const R = 3958.8;
  const dLat = toRad(b.lat - a.lat);
  const dLng = toRad(b.lng - a.lng);
  const h =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(a.lat)) * Math.cos(toRad(b.lat)) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
};

/** Nearest municipalities to a town (any county), with rounded distances. */
export const nearbyTowns = (town: MaTown, n = 8): { town: MaTown; miles: number }[] =>
  MA_TOWNS.filter((t) => t.slug !== town.slug)
    .map((t) => ({ town: t, miles: milesBetween(town, t) }))
    .sort((a, b) => a.miles - b.miles)
    .slice(0, n)
    .map((x) => ({ town: x.town, miles: Math.round(x.miles) }));

/** People per square mile of land — a factual density figure for copy. */
export const density = (t: MaTown): number | null =>
  t.population2020 && t.landSqmi ? Math.round(t.population2020 / t.landSqmi) : null;

export const formatNumber = (n: number | null): string =>
  n === null ? "—" : n.toLocaleString("en-US");
